def _named_sources(sources, expected):
    if type(sources) is not dict or set(sources) != set(expected):
        raise ValueError('the complete finite Scene-entry source dependency set is required')
    for path, wanted in expected.items():
        actual = {}
        for node in ast.parse(sources[path]).body:
            if isinstance(node,(ast.FunctionDef,ast.ClassDef)) and node.name in wanted:
                if node.name in actual:
                    raise ValueError('duplicate complete source owner: ' + node.name)
                actual[node.name] = ast.dump(node,include_attributes=False)
        if actual != wanted:
            raise ValueError('complete Scene-entry dependency differs: ' + path)


def admit_scene_entries_source(modules, reused_sources, scalar_sources):
    """Check only complete named source, without entering any game function."""
    if type(modules) is not dict or set(modules) != set(EXPECTED_MODULE_ASTS):
        raise ValueError('both complete force and transport Frame modules are required')
    for path, source in modules.items():
        if ast.dump(ast.parse(source),include_attributes=False) != EXPECTED_MODULE_ASTS[path]:
            raise ValueError('complete new Scene-entry Frame source differs: ' + path)
    _named_sources(reused_sources,EXPECTED_DEPENDENCY_ASTS)
    _named_sources(scalar_sources,EXPECTED_SCALAR_ASTS)
    return dict(confidence='confirmed_static_source_only_not_runtime_or_machine_acceptance',
        original_complete_owners=ORIGINAL_OWNERS, actual_nested_CALL_pairs=REAL_CALL_PAIRS,
        original_scalar_and_native_sources_retained=True, source_only=True,
        game_execution=False, machine_lowering=False, formal_new_CODE_bytes=0)
